from kit import *
A='workout'
CUE='Soft knees, push the hips back. Keep the bar close to your legs.'
goblet_c=f'''<div class="collapsed"><div class="dt">{ic('check',20,2.6)}</div><div class="f1"><div class="t-bodym">Goblet squat</div><div class="t-sub ell" style="font-size:13.5px">4 sets · best 16 kg × 12 · <span class="added">+1 set by you</span></div></div><span style="color:var(--ink3)">{ic('chevron-down',20,2)}</span></div>'''
def rdl(s3='cur',s3kg='<span class="ghost">40</span>',s3r='<span class="ghost">10</span>',focus='kg',pr=True,legend=True,extra_rows=''):
    r3=setrow(s3,3,'37.5 × 9',s3kg,s3r,focus=focus if s3=='cur' else None)
    lg=f'<div class="t-cap" style="margin:8px 0 0;display:flex;align-items:center;gap:6px"><span style="width:8px;height:8px;border-radius:4px;background:var(--ghost);display:inline-block"></span>Purple values are Rahul’s targets. Tap ✓ to log them as is.</div>' if legend else ''
    return f'''<div class="ex">{exhead("Romanian deadlift","dumbbell",("3 × 8–10 · 40 kg","1:30","Note"),CUE)}{sethead()}
{setrow("done",1,"37.5 × 10","40","10")}{setrow("done",2,"37.5 × 10","42.5","10",pr=pr)}{r3}{extra_rows}{lg}<div class="addset">{ic('plus',17,2.4)}Add set</div></div>'''
lunge_h=f'''<div class="wsep"></div><div class="ex">{exhead("Walking lunge","footprints",("3 × 12 / leg","1:00","Note"))}{sethead(True)}{setrow("up",1,"12 / leg","",'<span class="ghost">12</span>',bw=True)}{setrow("up",2,"12 / leg","",'<span class="ghost">12</span>',bw=True)}</div>'''
def log(body,nav=None,stats=None,over='',cls='white'):
    return (nav or wnav())+(stats or wstats())+f'<div class="wlog">{body}</div>'+over
# ---- Workout tab ----
prev=lambda n,t:f'<div class="row sp" style="padding:9px 0;border-top:.5px solid var(--line)"><span class="row" style="gap:10px"><span class="th" style="width:30px;height:30px">{ic("dumbbell",15,2)}</span><span class="t-body" style="font-size:15px">{n}</span></span><span class="t-sub tnum">{t}</span></div>'
EXS=[("Goblet squat","3 × 12 · 16 kg"),("Romanian deadlift","3 × 8–10 · 40 kg"),("Walking lunge","3 × 12 / leg"),("Lying leg curl","3 × 12 · 25 kg"),("Calf raise","3 × 15 · 30 kg")]
WDAYS=[('S','8','rest'),('M','9','ok'),('T','10','rest'),('W','11','ok'),('T','12','ok'),('F','13','rest'),('S','14','today')]
def wtab(card,extra='',eb='Week 3 of 12 · Rahul’s plan',bannerh=''):
    return f'''<div class="content">{lhdr("Workout",eb)}{week(days=WDAYS)}{bannerh}{card}{extra}</div>{fade()}{tabbar("Workout")}'''
def daycard(top,body,cta):
    return f'<div class="card pad" style="margin-top:14px">{top}{body}<div style="margin-top:14px">{cta}</div></div>'
top_ns=f'''<div class="row sp"><span class="t-cap" style="color:var(--brand);font-weight:600">TODAY · 6:30 PM</span><span class="t-cap">about 50 min</span></div><div class="t-title" style="margin-top:4px">Lower body B</div>
<div class="cue" style="margin:8px 0 6px">{coach_av()}<div class="t-sub" data-wrapok="1" style="color:var(--ink)">Go heavier on RDLs if set 2 feels easy.</div></div>'''
screen('W-01a-workout-tab-not-started','Workout tab, not started',wtab(daycard(top_ns,''.join(prev(n,t) for n,t in EXS),btn("Start workout",icon="play")),f'<div class="t-cap" style="text-align:center;margin-top:14px">This week: 3 of 4 done</div>'),A)
top_ip=f'''<div class="row sp"><span class="syncchip" style="background:var(--brand-tint);color:var(--brand)">{ic("timer",13,2.2)}In progress · 23:14</span><span class="t-cap tnum">7 of 18 sets</span></div><div class="t-title" style="margin-top:8px">Lower body B</div><div class="track" style="margin-top:10px"><i style="width:39%;background:var(--brand)"></i></div>'''
body_ip=f'''<div class="row" style="gap:10px;margin-top:14px;padding:10px 12px;border-radius:12px;background:var(--bg)"><span class="t-cap">UP NEXT</span><span class="t-body f1 ell" style="font-size:15px">Romanian deadlift · set 3</span><span class="t-sub tnum">40 × 10</span></div>'''
screen('W-01b-workout-tab-in-progress','Workout tab, in progress',wtab(daycard(top_ip,body_ip+''.join(prev(n,t) for n,t in EXS[2:]),btn("Continue workout",icon="play")+f'<div style="margin-top:6px">{btn("Finish now","textb")}</div>')),A)
top_dn=f'''<div class="row sp"><span class="syncchip" style="background:var(--done-tint);color:var(--done)">{ic("check",13,2.6)}Done · 7:24 pm</span>{tag(ic("medal",11,2.4)+"1 PR","pr")}</div><div class="t-title" style="margin-top:8px">Lower body B</div>
<div class="row" style="margin-top:12px;gap:8px">{''.join(f'<div class="f1" style="background:var(--bg);border-radius:12px;padding:10px"><div class="t-cap">{l}</div><div class="n-md">{v}</div></div>' for l,v in [("Duration","52 min"),("Volume","4,120 kg"),("Sets","17 / 18")])}</div>
<div class="row" style="gap:6px;margin-top:12px" ><span style="color:var(--done)">{ic("send",15,2.2)}</span><span class="t-sub">Shared with Rahul at 7:24 pm</span></div>'''
screen('W-01c-workout-tab-done','Workout tab, done',wtab(daycard(top_dn,'',btn("View summary","secondary")),f'''{sec("Next","","margin:20px 2px 10px")}<div class="card pad row" style="gap:12px"><div class="th">{ic("dumbbell",20,2)}</div><div class="f1"><div class="t-bodym">Upper body A</div><div class="t-sub">Mon 16 Nov · 6:30 pm</div></div></div>''',WDAYS and 'Week 3 of 12 · 4 of 4 done'),A)
screen('TR-10a-workout-rest-day','Workout tab, rest day',f'''<div class="content">{lhdr("Workout","Friday, 13 Nov · rest day")}{week(sel=5,on=5,days=WDAYS)}
<div class="card" style="margin-top:14px;padding:22px 18px">{empty("moon-star","Rest day","Rahul planned recovery today. A walk counts, so your steps still show on Today.")}</div>
{sec("Next","","margin:20px 2px 10px")}<div class="card pad row" style="gap:12px"><div class="th">{ic("dumbbell",20,2)}</div><div class="f1"><div class="t-bodym">Lower body B</div><div class="t-sub">Tomorrow · 6:30 pm · 5 exercises</div></div><span class="chev">{ic("chevron-right",18,2.2)}</span></div></div>{fade()}{tabbar("Workout")}''',A)
screen('TR-10b-workout-no-plan','Workout tab, no plan yet',f'''<div class="content">{lhdr("Workout","Saturday, 14 Nov")}
<div class="card" style="margin-top:20px;padding:26px 18px">{empty("clipboard-check","No workouts planned yet","Rahul hasn’t added workouts to your plan. You’ll get a notification when he does.",btn("Message Rahul on WhatsApp","outline",icon="message-circle"))}</div></div>{tabbar("Workout")}''',A)
missed=f'<div style="margin-top:12px">{banner("You missed <b>Upper body B</b> on Thu. Did it anyway?","warn","calendar-x","Log it")}</div>'
screen('TR-10c-workout-missed-banner','Missed earlier session, late-log banner',wtab(daycard(top_ns,''.join(prev(n,t) for n,t in EXS[:3]),btn("Start workout",icon="play")),'',bannerh=missed).replace("('T','12','ok')","('T','12','miss')"),A)
# ---- Active log ----
g_start=f'''<div class="ex">{exhead("Goblet squat","dumbbell",("3 × 12 · 16 kg","1:00","Note"),"Sit between your heels. Chest tall.")}{sethead()}
{setrow("cur",1,"14 × 12",'<span class="ghost">16</span>','<span class="ghost">12</span>',focus=None)}{setrow("up",2,"14 × 12",'<span class="ghost">16</span>','<span class="ghost">12</span>')}{setrow("up",3,"14 × 12",'<span class="ghost">16</span>','<span class="ghost">12</span>')}
<div class="addset">{ic('plus',17,2.4)}Add set</div></div><div class="wsep"></div><div class="ex">{exhead("Romanian deadlift","dumbbell",("3 × 8–10 · 40 kg","1:30","Note"))}</div>'''
screen('W-02-active-start','Active log, start of session',log(g_start,stats=wstats('0:42','0','0','18',2)),A,cls='white')
screen('W-03-active-mid','Active log, mid-session',log(goblet_c+rdl()+lunge_h),A,cls='white')
end_body=f'''<div class="ex">{exhead("Calf raise","dumbbell",("3 × 15 · 30 kg","0:45","Note"))}{sethead()}{setrow("done",1,"30 × 15","30","15")}{setrow("done",2,"30 × 15","30","15")}{setrow("done",3,"30 × 15","30","14")}<div class="addset">{ic('plus',17,2.4)}Add set</div></div>
<div class="wsep"></div><div class="ex"><div class="exh" style="margin-top:6px"><div class="th">{ic("dumbbell",20,2)}</div><div class="f1"><div class="exname">Hip thrust</div></div>{tag("Added by you","brand")}<span style="color:var(--ink2)">{ic("ellipsis-vertical",20,2.2)}</span></div>
<div class="t-cap" style="margin-top:2px">Not in Rahul’s plan · he’ll see it on your summary</div>{sethead()}{setrow("done",1,"—","40","12")}{setrow("cur",2,"—",'<span class="ph" style="color:var(--ink4)">kg</span>','<span style="color:var(--ink4)">reps</span>')}</div>
<div class="ex" style="margin-top:20px">{btn("Add exercise","tint",icon="plus")}<div style="margin-top:10px">{btn("Discard workout","dangerq")}</div></div>'''
screen('W-03b-active-end-of-list','Active log, end of list: add exercise, discard',log(end_body,stats=wstats('48:10','3,960','17','19',89)),A,cls='white')
screen('W-04-active-keypad','Compact set keypad, editing kg',log(goblet_c+rdl(s3kg='42.5',focus='kg',legend=False))+kpad_set('kg'),A,cls='white')
screen('W-05a-rest-running','Rest running, slim bar',log(goblet_c+rdl()+lunge_h)+restbar(),A,cls='white')
screen('W-05b-rest-ended','Rest ended',log(goblet_c+rdl()+lunge_h)+f'''<div class="restbar" style="background:var(--done)"><div class="col f1"><span style="font-size:12px;font-weight:500;color:rgba(255,255,255,.8)">Rest done</span><span style="font-size:17px;font-weight:700;letter-spacing:-.3px">Next: set 3 · 40 kg × 10</span></div><div class="rb" style="background:#fff;color:var(--done)">OK</div></div>''',A,cls='white')
swipe=f'''<div style="position:relative;margin:0 -16px;height:48px;overflow:hidden"><div class="row" style="position:absolute;right:0;top:0;bottom:0"><div style="width:84px;height:48px;background:#8F8BA6;color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:12.5px;font-weight:600">{ic("skip-forward",18,2.2)}Skip</div><div style="width:84px;height:48px;background:var(--crit);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:12.5px;font-weight:600">{ic("trash-2",18,2.2)}Delete</div></div>
<div style="position:absolute;left:-168px;width:393px;top:0" data-offok="1">{setrow("cur",3,"37.5 × 9",'<span class="ghost">40</span>','<span class="ghost">10</span>').replace('class="sgrid sr cur"','class="sgrid sr cur" style="margin:0;background:#F7F5FF"')}</div></div>'''
rdl_sw=rdl().split(setrow("cur",3,"37.5 × 9",'<span class="ghost">40</span>','<span class="ghost">10</span>',focus='kg'))
screen('W-08-swipe-set','Swipe a set: Skip or Delete',log(goblet_c+rdl_sw[0]+swipe+rdl_sw[1]+lunge_h),A,cls='white')
menu=lambda rows:'<div class="group" style="box-shadow:none;background:var(--bg)">'+''.join(rows)+'</div>'
screen('W-09-exercise-menu','Exercise ⋯ menu',log(goblet_c+rdl()+lunge_h)+sheet(f'''<div class="row" style="gap:12px;margin:0 0 14px"><div class="th">{ic("dumbbell",20,2)}</div><div class="f1"><div class="t-head">Romanian deadlift</div><div class="t-sub">3 × 8–10 · 40 kg · rest 1:30</div></div></div>
{menu([li("How to do it","",'circle-play',chev=True),li("History and records","",'clock'),li("Replace exercise","Rahul’s alternatives first",'repeat'),li("Ask Rahul about this","Opens WhatsApp with this exercise",'message-circle'),li("Skip exercise","Rahul sees it as skipped",'skip-forward',chev=False),li("Remove from today","",'trash-2',icol='var(--crit)',ibg='var(--crit-tint)',chev=False,cls='danger')])}''',bgc=True),A,cls='white')
prb=f'''<div style="position:absolute;top:112px;left:16px;right:16px;z-index:50;border-radius:16px;background:linear-gradient(135deg,#FFF4D6,#FFE7A8);box-shadow:0 10px 26px rgba(169,120,10,.25);padding:12px 14px;display:flex;gap:12px;align-items:center">
<div style="width:40px;height:40px;border-radius:20px;background:#fff;color:var(--pr);display:flex;align-items:center;justify-content:center">{ic("trophy",21,2.2)}</div><div class="f1"><div class="t-bodym" style="color:#5C4100">New personal record</div><div class="t-sub tnum" style="color:#7A5A00">Romanian deadlift · 42.5 kg × 10</div></div></div>'''
screen('W-12-pr-moment','Live PR moment',log(goblet_c+rdl()+lunge_h)+prb+restbar('1:24','Rest · next set 3',8),A,cls='white')
screen('W-13-edit-logged-set','Tap a logged set: edit, undo or delete',log(goblet_c+rdl()+lunge_h)+sheet(f'''<div class="row sp" style="margin-bottom:12px"><div><div class="t-head">Set 2 · Romanian deadlift</div><div class="t-sub tnum">Logged 42.5 kg × 10 at 6:51 pm · PR</div></div></div>
<div class="row" style="gap:10px"><div class="f1"><div class="t-label" style="margin-bottom:6px">kg</div><div class="inp focus tnum" style="font-size:20px;font-weight:600;justify-content:center">42.5</div></div><div class="f1"><div class="t-label" style="margin-bottom:6px">Reps</div><div class="inp tnum" style="font-size:20px;font-weight:600;justify-content:center">10</div></div></div>
<div class="t-cap" style="margin-top:10px">Rahul sees edited sets with an “edited” mark.</div>
<div class="col" style="gap:8px;margin-top:16px">{btn("Save changes")}<div class="row" style="gap:8px">{btn("Mark not done","secondary",style="flex:1")}{btn("Delete set","dangerq",style="flex:1")}</div></div>'''),A,cls='white')
screen('W-15-discard-confirm','Discard workout confirm',log(goblet_c+rdl()+lunge_h)+dialog("Discard this workout?","7 logged sets will be deleted. Rahul won’t see this session.",[btn("Discard workout","danger"),btn("Keep logging","secondary")],"trash-2"),A,cls='white')
fe=lambda n,s:f'<div class="li" style="--inset:14px"><div class="f1"><div class="t-body" style="font-size:15px">{n}</div><div class="t-sub" style="font-size:13px">{s}</div></div><span class="link">Go to</span></div>'
screen('W-16-finish-early','Finish early: what is not logged',log(goblet_c+rdl()+lunge_h)+sheet(f'''<div class="t-title">Finish early?</div><div class="t-sub" style="margin-top:4px">11 of 18 sets aren’t logged. Rahul will see “finished early”.</div>
<div class="group" style="margin-top:14px;box-shadow:none;background:var(--bg)">{fe("Romanian deadlift","Set 3")}{fe("Walking lunge","3 sets")}{fe("Lying leg curl","3 sets")}{fe("Calf raise","3 sets · skipped")}</div>
<div class="col" style="gap:8px;margin-top:16px">{btn("Finish anyway")}{btn("Keep going","secondary")}</div>'''),A,cls='white')
st=lambda l,v,u='':f'<div class="f1" style="background:var(--bg);border-radius:14px;padding:12px"><div class="t-cap">{l}</div><div class="n-lg" style="margin-top:2px">{v}<span class="unit" style="font-size:14px"> {u}</span></div></div>'
chg=lambda i,c,t,s,r:f'<div class="li" style="--inset:58px"><div class="lic" style="background:{c[0]};color:{c[1]}">{ic(i,16,2.2)}</div><div class="f1"><div class="t-body" style="font-size:15px">{t}</div><div class="t-sub" style="font-size:13px">{s}</div></div><span class="t-sub tnum">{r}</span></div>'
eff=''.join(f'<span class="tnum" style="flex:1;height:36px;border-radius:9px;background:var(--fill);display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:600;color:var(--ink2)">{i}</span>' for i in range(1,11))
screen('W-17a-summary','Workout summary before saving',f'''<div class="content">{nav("",left="")}
<div class="t-cap" style="color:var(--brand);font-weight:600">LOWER BODY B · SAT 14 NOV</div><div class="t-large">Workout done</div>
<div class="row" style="gap:8px;margin-top:14px">{st("Duration","52","min")}{st("Volume","4,120","kg")}{st("Sets","17","/ 18")}</div>
<div class="card row" style="gap:12px;margin-top:12px;padding:12px 14px;background:var(--pr-tint);box-shadow:none"><span style="color:var(--pr)">{ic("trophy",22,2.2)}</span><div class="f1"><div class="t-bodym" style="color:#5C4100">1 new record</div><div class="t-sub tnum" style="color:#7A5A00">Romanian deadlift · 42.5 kg × 10</div></div></div>
<div class="t-label glabel">Changed from the plan · Rahul sees this</div><div class="group">{chg("plus",("var(--brand-tint)","var(--brand)"),"Goblet squat","1 set added by you","+1")}{chg("arrow-up-right",("var(--done-tint)","var(--done)"),"Romanian deadlift","Sets 2–3 heavier","40 → 42.5")}{chg("skip-forward",("var(--fill)","var(--ink2)"),"Calf raise","Set 3 skipped","–1")}</div>
<div class="row sp glabel"><span class="t-label">How hard did it feel?</span><span class="t-cap">Optional</span></div><div class="row" style="gap:4px">{eff}</div>
{field("Note for Rahul","",ph="Anything he should know?")}</div>
<div class="stick">{btn("Save and share with Rahul",icon="send")}</div>''',A)
screen('W-17b-summary-shared','Summary saved and shared with coach',f'''<div class="content" style="top:120px;text-align:center">
<div style="width:76px;height:76px;border-radius:38px;background:var(--done-tint);color:var(--done);display:flex;align-items:center;justify-content:center;margin:0 auto">{ic("check",38,2.6)}</div>
<div class="t-large" style="margin-top:18px">Shared with Rahul</div><div class="t-sub" style="margin-top:6px">Saved at 7:24 pm. He’ll see your sets, the record and your note.</div>
<div class="card pad" style="margin-top:26px;text-align:left"><div class="row sp"><span class="t-bodym">This week</span><span class="t-sub tnum">4 of 4 done</span></div>
<div class="row" style="gap:6px;margin-top:12px">{''.join(f'<div class="f1 col" style="align-items:center;gap:6px"><span class="t-cap">{d}</span><span style="width:30px;height:30px;border-radius:15px;display:flex;align-items:center;justify-content:center;{s}">{ic("check",15,2.8) if "done" in s else ""}</span></div>' for d,s in [("S","background:var(--fill)"),("M","background:var(--done);color:#fff;done"),("T","background:var(--fill)"),("W","background:var(--done);color:#fff;done"),("T","background:var(--done);color:#fff;done"),("F","background:var(--fill)"),("S","background:var(--done);color:#fff;box-shadow:0 0 0 3px var(--done-tint);done")])}</div></div></div>
<div class="stick" style="background:transparent;border:0">{btn("Done")}</div>''',A)
screen('W-18-resume-after-kill','Resume after the app was closed',wtab(daycard(top_ip,body_ip,btn("Continue workout",icon="play")))+dialog("Pick up where you left off?","Lower body B was in progress. 7 sets were logged, the last at 6:52 pm.",[btn("Resume workout"),btn("Finish and save","secondary"),btn("Discard","textb",style="color:var(--crit)")],"timer","var(--brand)","var(--brand-tint)"),A)
pstats=wstats('23:14','2,140','7','18',39,'var(--warn)')
screen('W-19-paused','Paused session',log(f'<div style="padding:10px 16px 0">{banner("Paused. The timer stopped at 23:14.","warn","pause","Resume")}</div>'+goblet_c+rdl(legend=False),stats=pstats),A,cls='white')
screen('W-20-active-offline','Active log, offline',log(goblet_c+rdl()+lunge_h,nav=wnav(sub='<span style="color:var(--warn);font-weight:600">Offline</span> · sets save on your phone')),A,cls='white')
exrow=lambda n,m,sel,tagx='':f'<div class="li" style="--inset:66px"><div class="th">{ic("dumbbell",19,2)}</div><div class="f1"><div class="t-body">{n}</div><div class="t-sub" style="font-size:13px">{m}</div></div>{tagx}<span style="width:24px;height:24px;border-radius:12px;display:flex;align-items:center;justify-content:center;{"background:var(--brand);color:#fff" if sel else "box-shadow:inset 0 0 0 1.5px var(--ink4)"}">{ic("check",14,3) if sel else ""}</span></div>'
screen('W-21a-add-exercise','Add exercise, Rahul’s picks first',f'''<div class="content" style="background:#fff;top:0;padding-top:54px;bottom:0">{nav("Add exercise",left="Cancel",right='<span class="navbtn strong">Add (1)</span>')}
<div class="search">{ic("search",18,2)}Search 640 exercises</div>
<div class="t-label glabel">Rahul’s picks for this session</div><div class="group" style="box-shadow:none">{exrow("Hip thrust","Glutes · barbell",True)}{exrow("Bulgarian split squat","Quads · dumbbell",False)}{exrow("Back extension","Lower back · bodyweight",False)}</div>
<div class="t-label glabel">Recent</div><div class="group" style="box-shadow:none">{exrow("Leg press","Quads · machine",False)}{exrow("Seated calf raise","Calves · machine",False)}{exrow("Plank","Core · bodyweight · timed",False)}</div>
<div class="t-cap row" style="gap:6px;margin-top:14px">{ic("info",14,2)}Rahul will see added exercises on your summary.</div></div>''',A,cls='white')
added=f'''<div class="wsep"></div><div class="ex"><div class="exh" style="margin-top:6px"><div class="th">{ic("dumbbell",20,2)}</div><div class="f1"><div class="exname">Hip thrust</div></div>{tag("Added by you","brand")}<span style="color:var(--ink2)">{ic("ellipsis-vertical",20,2.2)}</span></div>
<div class="t-cap" style="margin-top:2px">Not in Rahul’s plan. Last time: 40 kg × 12</div>{sethead()}{setrow("cur",1,"40 × 12",'<span style="color:var(--ink4)">40</span>','<span style="color:var(--ink4)">12</span>',focus='kg')}<div class="addset">{ic('plus',17,2.4)}Add set</div></div>'''
screen('W-21b-added-exercise','Added exercise in the log',log(goblet_c+rdl(legend=False)+added),A,cls='white')
seg2=lambda sel:f'<div style="margin-top:6px">{seg(["How to","History"],sel)}</div>'
